// Retained community research: observations only, separate from official remedies.
const reports={
 fragment:{title:'入口の異物除去後に再発した報告',body:'入口の黒い異物を除去して印刷できた後、翌日に再発した利用者報告です。破片除去だけで恒久的に直るとは限りません。',url:'https://forum.prusa3d.com/forum/prusa-core-one-assembly-and-first-prints-troubleshooting/core-one-filament-feed-issue/'},
 gear:{title:'ギアへの巻き込みで分解できない報告',body:'PPがギアに絡み、プレートも外せないという未解決の利用者報告です。原因や修理完了は確認されていません。',url:'https://forum.prusa3d.com/forum/prusa-core-one-assembly-and-first-prints-troubleshooting/main-plate-cant-be-removed-filament-stuck/'},
 flow:{title:'公式の詰まり対処後に印刷へ戻った報告',body:'コールドプルなどでは改善せず、公式の詰まり対処後にロードと短い印刷ができたという報告です。効いた操作と長期の再発有無は不明です。',url:'https://forum.prusa3d.com/forum/prusa-core-one-hardware-firmware-and-software-help/fillament-refusing-to-load-till-nozzle-knocking-sound/'}
};
export function japaneseDiagnostics(base){
 return {...base,
 start:node('どんな症状ですか？','標準Nextruder搭載のCORE One / CORE One+向けです。実機で起きている症状を選んでください。', {choices:[
  choice('フィラメントをロード・アンロードできない','loading-direction'),
  choice('吐出が細い・印刷途中から出なくなる','print-flow'),
  choice('音・レイヤーずれ・動きが気になる','movement'),
  choice('初層・ベッド・ノズル清掃テストの問題','first-layer'),
  choice('ファン・温度・電装のエラー','error-kind'),
  choice('フィラメントセンサーの反応がおかしい','sensor-kind'),
  choice('起動・セルフテスト・画面の問題','startup'),
  choice('定期メンテナンスをしたい','routine'),
  choice('HT・V6・INDX・MMUなど装備が異なる','other-configuration'),
  choice('該当する症状がない・わからない','support')]}),
 'loading-direction':node('どちらの操作で止まりますか？','画面にエラーが出ている場合は、番号まで確認します。クリック音だけでは詰まりの場所を決められません。',{sources:['clog','obstruction','stuck'],choices:[
  choice('ロード中に止まる','location'),choice('アンロードできない','unloading'),choice('Loading obstruction #31119','obstruction'),choice('Stuck filament #31101','supply'),choice('止まる場所がわからない','path')]}),
 unloading:node('アンロードの指示と残片を確認する','実機のアンロード操作と温度表示を確認します。無理に引かず、途中で折れた場合は側面入口・PTFE・ギア直下を分けて確認してください。MMUのアンロードはMMU専用ガイドを使います。',{sources:['clog','stuck'],inspection:{task:'clog',step:2},choices:[choice('側面入口・PTFEで止まる','supply'),choice('ギアの下に破片が見える','fragment-check'),choice('位置がわからない・抜けない','support')]}),
 path:node('フィラメントの通路を順に確認する','側面入口・PTFE、Nextruder入口、送りギアとアイドラー、ギア直下からヒートブレークへ続く通路、ホットエンドとノズル先端を分けます。3Dのハイライトは確認候補です。実機で詰まった場所を示すものではありません。',{sources:['clog','stuck','sensor'],inspection:{task:'clog',step:0},choices:[choice('側面入口・PTFEを確認する','supply'),choice('Nextruder入口を確認する','inlet'),choice('送りギアとアイドラーを確認する','gear'),choice('ギア直下の残片を確認する','fragment-check'),choice('ホットエンド内とノズルを確認する','hotend-path'),choice('止まる場所がわかった','location')]}),
 gear:node('送りギアとアイドラーを確認する','停止・冷却・電源切断後に、公式手順でアイドラーを開き、粉・欠片・巻き込みを確認します。送りギアの歯とアイドラーベアリングには注油しません。ギアボックスの分解は別の作業で、PG-assembly-adapterが必要です。',{sources:['care','clog'],inspection:{task:'clog',step:2},tasks:['extruder'],observations:[reports.gear],choices:[choice('清掃後もギアの下で止まる','fragment-check'),choice('少しは出るが、吐出が弱い','partial'),choice('アイドラーが開かない・巻き込みが取れない','gear-stuck'),choice('通常どおりロード・吐出できる','resolved')]}),
 'gear-stuck':node('開かない部品を無理に外さない','アイドラーの開放とギアボックスの分解は区別します。巻き込みや固着で開かない場合は、プレートをこじらず、写真と症状をサポートへ伝えてください。ギアボックスを分解する場合は、公式手順の治具と再組立後の位置合わせが必要です。',{sources:['care','clog','support'],inspection:{task:'clog',step:2},choices:[choice('サポートへ伝える内容を確認する','support'),choice('アイドラーを開けられた','gear')]}),
 'fragment-check':node('送りギアの下に、つかめる破片がありますか？','アイドラーを開く方法は公式記事で確認します。ギア直下からヒートブレークへ続くノズルチューブの上端に、折れたフィラメントが出ていないか見ます。見えないことだけでは、管内に詰まりがないとは判断できません。',{sources:['clog'],inspection:{task:'clog',step:3},observations:[reports.fragment],choices:[choice('フィラメントが突き出し、先端をつかめる','fragment'),choice('見えるが、つかめない・異物か判断できない','hotend-path'),choice('突き出した破片は見えない','hotend-path'),choice('3Dで入口の位置を確かめたい','tube'),choice('アイドラーを開けられない','gear-stuck')]}),
 tube:node('送りギアからヒートブレークまでを表示する','ハイライトはギア直下のチューブ入口とヒートブレークです。実機に突き出したフィラメントがあるか見比べます。見えない破片を探して工具を奥へ差し込まず、見える破片の除去と管内の詰まり対処を分けます。',{sources:['clog'],inspection:{task:'clog',step:3},choices:[choice('実機の入口を確認した','fragment-check')]}),
 fragment:node('突き出したフィラメントの除去手順へ','ノズルチューブ上端に出たフィラメントをつかめる場合の公式手順です。実機の温度メニューを使う加熱条件と上への抜き方を確認します。冷えたまま無理に引かず、外部の熱源は使いません。配線や正体不明の異物はつかまないでください。',{sources:['clog'],inspection:{task:'clog',step:3},tasks:['fragment'],choices:[choice('取り除けた。流れを確認する','flow'),choice('つかめない・抜けない','hotend-path'),choice('配線の傷や異物が気になる','support')]}),
 'hotend-path':node('ヒートブレーク・ホットエンド内と先端を分ける','ギアを越えても出ない場合は、チューブやヒートブレークを含む上流の通路とノズル先端が確認候補です。外から見えない詰まりの位置は断定できません。突き出した破片をつかむ方法を流用せず、公式記事で吐出の状態に合う対処を選びます。',{sources:['clog'],inspection:{task:'clog',step:3},choices:[choice('ロード時に少しは出る','flow'),choice('ロード時にまったく出ない','blocked'),choice('まだ吐出を確認していない','flow-check'),choice('ノズル交換後から起きる','hotend-seating'),choice('温度や加熱のエラーがある','hotend-temperature'),choice('損傷がある・判断できない','support')]}),
 partial:node('少しは出る場合の対処を選ぶ','吐出が細い・途切れる原因には、供給抵抗、ギアの粉、上流の残片、ノズル内の部分詰まりなどがあります。供給側とギア・残片を確認してから、装着したノズルに合う清掃を選びます。',{sources:['clog','cold'],inspection:{task:'clog',step:4},choices:[choice('供給側をまだ確認していない','supply'),choice('ギアや残片をまだ確認していない','gear'),choice('通路を確認した。コールドプルの適合を見る','coldpull-compatibility'),choice('ロード時は正常で、印刷時だけおかしい','print-settings'),choice('まったく出なくなった','blocked')]}),
 'coldpull-compatibility':node('コールドプルに対応したノズルですか？','コールドプルは、一部でも樹脂が出る場合の清掃方法です。Nozzle Xには使いません。装着品が不明な場合は、ノズルの種類を公式記事で確認してください。HFノズルには清掃針を入れません。',{sources:['cold','nozzleTypes','clog'],inspection:{task:'clog',step:4},choices:[choice('Nozzle Xではなく、公式記事の対応ノズルだった','coldpull-ready'),choice('Nozzle X・種類が不明・装備が異なる','nozzle-other'),choice('樹脂がまったく出ない','blocked')]}),
 'coldpull-ready':node('自動コールドプルを確認する','少しは吐出し、対応ノズルと確認できた場合の手順です。PLAを30 cm以上用意し、実機のControl → Cold Pullの案内に従います。自動処理に手動手順の温度や抜くタイミングを混ぜないでください。',{sources:['cold'],tasks:['coldpull'],choices:[choice('通常の流れに戻った','resolved'),choice('流れが戻らない','blocked'),choice('適合や操作に迷う','support')]}),
 'nozzle-other':node('装着したノズルに合う方法を確認する','Nozzle Xはコールドプルの対象外です。種類が不明なまま清掃針や加熱・引き抜き方法を選ばず、公式のノズル一覧と購入した部品の情報を照合します。V6アダプターなど装備が異なる場合は、その専用手順を使います。',{sources:['nozzleTypes','cold','support'],choices:[choice('装備に合う手順を確認したい','other-configuration'),choice('ノズルの適合がわかったので戻る','coldpull-compatibility'),choice('判断できない','support')]}),
 blocked:node('まったく出ない場合は通路の確認へ','吐出しないことだけでは、ノズル先端とその上流のどちらが詰まったか決められません。供給側、送りギア・アイドラー、ギア直下の残片を確認します。完全に出ない状態でコールドプルを始めないでください。',{sources:['clog','cold'],inspection:{task:'clog',step:4},choices:[choice('供給側をまだ確認していない','supply'),choice('ギアとアイドラーをまだ確認していない','gear'),choice('ギア直下に破片が見える','fragment-check'),choice('通路を確認したが、まだ出ない','blocked-remedy'),choice('ファンや温度のエラーがある','error-kind'),choice('判断できない','support')]}),
 'blocked-remedy':node('公式の詰まり除去・ノズル交換を確認する','標準Nextruder用の該当手順で、新しいフィラメントによる詰まり除去を確認します。流れが戻らなければ、ノズル先端より上流に詰まりが残る可能性があり、公式のノズル交換手順へ進みます。HFノズルへ清掃針を入れず、装着品と手順が合うか確認してください。',{sources:['clog','nozzleTypes'],inspection:{task:'clog',step:3},tasks:['feed-clear','nozzle'],observations:[reports.flow],choices:[choice('装着したノズルが不明・標準装備と異なる','other-configuration'),choice('通常の流れに戻った','resolved'),choice('対処しても改善しない・判断できない','support')]}),
 'print-flow':node('いつ吐出が悪くなりますか？','ロード直後から悪い場合と、印刷中に悪化する場合を分けます。',{sources:['clog'],choices:[choice('ロード時から細い・途切れる','flow'),choice('初めは出るが、印刷中に出なくなる','time-dependent'),choice('ノズル交換後から起きる','hotend-seating'),choice('まだロード時の流れを確認していない','flow-check')]}),
 'time-dependent':node('材料・換気・冷却を確認する','材料とノズルに合うスライサープロファイル、チャンバーの換気、ホットエンドファンを確認します。熱クリープと決めつけず、詰まりや供給抵抗も調べます。',{sources:['clog','selftest'],choices:[choice('PLAなどでチャンバーが熱くなる','ventilation'),choice('ホットエンドファンが回らない・エラーが出る','fan-kind'),choice('ギアが空回りする・クリックする','gear'),choice('交換後の挿入位置が気になる','hotend-seating'),choice('条件を見直しても再発する','support')]}),
 ventilation:node('材料に合う換気を確認する','PLAなど低温材料の印刷では、公式説明に従って換気を確保します。チャンバーを昇温したい場合とは操作が異なります。材料・室温・発生までの時間を控えて、同じ条件でも再発しないか確認します。',{sources:['clog'],choices:[choice('ファンも確認したい','fan-kind'),...again]}),
 'hotend-seating':node('ホットエンドの挿入と固定を確認する','室温まで冷却し、電源を切ってコードを抜いてから確認します。ホットエンドを奥まで差し込み、上へ支えたまま両つまみネジで固定します。銅色リングの見え方だけで深さを決めず、公式Webの接写と照合してください。',{sources:['seating'],inspection:{task:'clog',step:3},tasks:['nozzle','hotend'],choices:again}),
 movement:node('どの動きに問題がありますか？','異音だけを頼りにベルトを締めたり、部位の違う潤滑剤を塗ったりしないでください。',{sources:['shifting','care'],choices:[choice('X・Y方向でずれる／ヘッドが引っ掛かる','xy-motion'),choice('ベッドの上下・Z軸が気になる','z-motion'),choice('ファンが回ると音がする','fan-kind'),choice('フィラメントを送ると音がする','gear'),choice('音の場所がわからない','noise')]}),
 'xy-motion':node('XYの抵抗・ベルト・プーリーを確認する','電源を切り、手や工具を退避してから、公式手順でX・Yと対角方向の引っ掛かりを確認します。清掃・注油とベルト調整は別々に行います。レイヤーずれが続く場合はプーリーの止めネジも公式図で確認します。',{sources:['shifting','belts'],tasks:['rod','rail','belts'],choices:[choice('ベルトの測り方を確認する','belt-method'),choice('清掃と注油を確認する','lubrication'),...again]}),
 'belt-method':node('使う測定方法を選ぶ','ガントリーの整列を先に確認します。マイクで弾いた音を測る方法と、実機がベルトを振動させるウィザードでは、位置と操作が異なります。',{sources:['belts'],choices:[choice('スマホのマイクでBelt Tunerを使う','belt-acoustic'),choice('実機のベルト調整ウィザードを使う','belt-wizard')]}),
 'belt-acoustic':node('Belt Tunerでマイク測定する','整列の確認はX中央・Y最前部、弾いて測るときはX右端・Y最前部です。CORE One → XY-beltを選び、上側・下側をそれぞれ測ります。調整後も左右の整列を確認します。',{sources:['belts'],tasks:['belts'],choices:again}),
 'belt-wizard':node('実機のベルト調整に従う','実機のSettings → Manual Belt Tuningを開きます。画面の指示に従い、選んだベルトの大きくゆっくりした安定した波を探します。マイク測定の位置や数値だけを転用せず、実機が示す調整を確認してください。',{sources:['belts'],choices:again}),
 'z-motion':node('Z整列とベッド下の異物を確認する','まずベッド下の異物と、引っ掛かった配線を確認します。#31111では公式のZ整列を確認し、繰り返す場合は台形ナットなどの点検へ進みます。自己判断で油種や注油量を決めず、直らない場合はサポートへ相談します。',{sources:['uneven','selftest'],tasks:['debris','initial-setup'],choices:again}),
 'first-layer':node('どの確認で止まりますか？','シート表面の問題、ベッドの整列、ロードセルのテストを分けます。',{sources:['selftest','cleaning','sheet'],choices:[choice('造形物が付かない・初層が乱れる','sheet-check'),choice('Nozzle Cleaning Failed #31834','nozzle-clean-test'),choice('Uneven bed #31111','z-motion'),choice('ロードセルのテストが失敗する','loadcell'),choice('ノズル交換後から起きる','hotend-seating')]}),
 'sheet-check':node('シートの種類と汚れを確認する','シートの両面とベッドの間に異物がないか確認します。洗浄剤はシートの種類に合わせてください。PA NylonにはIPA・アセトン、サテン・テクスチャーにはアセトンを使いません。',{sources:['sheet'],tasks:['sheet','debris'],choices:[choice('ノズル先端に樹脂が付いている','nozzle-clean-test'),...again]}),
 'nozzle-clean-test':node('ノズル清掃テストの失敗を確認する','ノズル外側とシートの汚れ、フィラメントの供給抵抗、ホットエンドの固定を順に確認します。このエラーだけでノズル内部の詰まりやロードセル故障とは決められません。',{sources:['cleaning'],tasks:['hotend-clean','sheet'],choices:[choice('ロードでも正常に出ない','flow'),choice('ノズルの固定を確認したい','hotend-seating'),choice('ロードセルのテストも失敗する','loadcell'),...again]}),
 loadcell:node('ロードセルテストを確認する','安定した台で、実機のテスト表示と公式説明を確認します。テスト中は指示のあるときだけノズルに触れ、他の操作を加えません。失敗を繰り返す場合はエラー番号と失敗した場面を控えます。',{sources:['selftest'],tasks:['initial-setup'],choices:[choice('ノズル交換後に失敗する','hotend-seating'),...again]}),
 'sensor-kind':node('どちらのセンサーですか？','側面入口のセンサーとNextruder内部のセンサーは別の部品です。実機のセンサー情報で、どちらの反応が変わらないか確認します。',{sources:['selftest','sensor'],choices:[choice('Nextruder内部のセンサー','sensor-test'),choice('側面入口のセンサー','side-sensor'),choice('Loading obstruction #31119','obstruction'),choice('装備がMMUなど標準と異なる','other-configuration'),choice('どちらかわからない','path')]}),
 'side-sensor':node('側面入口と配線を確認する','側面入口の残片と、センサー情報の反応を確認します。配線に触れる前は冷却・電源切断・抜栓が必要です。側面センサーの接続先はxBuddy拡張基板で、Nextruder内部センサーとは確認先が異なります。',{sources:['selftest'],inspection:{task:'clog',step:0},tasks:['electronics'],choices:[choice('入口に抵抗や破片がある','supply'),choice('通るが、センサーが反応しない','support'),choice('改善した','resolved')]}),
 'error-kind':node('画面のエラーはどの部位ですか？','表示された名称と番号、QRを確認します。温度の保護や回転数監視を無効にして使い続けないでください。',{sources:['errors'],choices:[choice('ファンのエラー','fan-kind'),choice('ホットエンドの温度・加熱','hotend-temperature'),choice('ヒートベッドの温度・過電流','bed-temperature'),choice('チャンバーの温度','chamber-temperature'),choice('配線・基板の点検を案内された','electrical'),choice('該当しない・番号が不明','support')]}),
 'fan-kind':node('どのファンを確認しますか？','造形物を冷やすプリントファン、ヒートシンクを冷やすホットエンドファン、背面のチャンバーファンを区別します。停止・冷却・抜栓してから異物と配線を確認します。',{sources:['care','selftest'],inspection:{task:'fans',step:0},tasks:['fans'],choices:[choice('プリントファン／#31816','print-fan-check'),choice('ホットエンドファン','hotend-fan-check'),choice('背面のチャンバーファン','chamber-fan-check'),choice('追加フィルターなど別のファン','other-configuration')]}),
 'print-fan-check':node('プリントファンの異物と接続を確認する','糸状の樹脂やほこりを取り除き、配線とコネクターを公式手順で確認します。清掃・接続確認後も回転エラーが残る場合に、公式交換手順かサポートへ進みます。',{sources:['printFan','selftest'],tasks:['fans','printfan'],choices:again}),
 'hotend-fan-check':node('ホットエンドファンを確認する','ファンの異物、向き、LoveBoardへの接続を公式手順で確認します。冷却不良は吐出が途中で止まる症状とも関係するため、交換後はファンテストと印刷中の状態を確認します。',{sources:['care','selftest'],tasks:['fans','hotendfan'],choices:again}),
 'chamber-fan-check':node('背面のチャンバーファンを確認する','背面ファンの異物と配線、実機のテストを公式説明で確認します。プリントファンやホットエンドファンの交換手順を流用しないでください。追加フィルターを使う場合は、その装備のガイドも確認します。',{sources:['selftest','care'],tasks:['fans','electronics'],choices:again}),
 'hotend-temperature':node('加熱を止め、冷却後に配線を確認する','#31208などの最低温度エラーや#31204の温度暴走保護は、ノズル詰まりの手順とは分けて対処します。冷却・抜栓後に、ヒーターとサーミスターの固定・配線・LoveBoard接続を確認します。損傷や異常があれば再加熱せずサポートへ進みます。',{sources:['hotendMin','runaway'],tasks:['electronics'],choices:[choice('ホットエンド交換を案内された','hotend-service'),choice('ヒートシンクNTCの交換を案内された','heatsink-service'),choice('再発する・配線に損傷がある','support'),choice('公式の確認を終えた','resolved')]}),
 'heatsink-service':node('ヒートシンク側NTCの交換対象を確認する','ヒートシンク側のNTCとノズルの温度センサーは別の部品です。交換対象がヒートシンクNTCと確認できた場合だけ、この公式手順を使います。詰まりやクリック音だけでセンサー交換とは判断しません。対象が不明な場合はサポートへ確認してください。',{sources:['heatsinkNtc'],tasks:['heatsink-ntc'],choices:[choice('交換後の公式テストを終えた','resolved'),choice('交換対象が違う・判断できない','support')]}),
 'hotend-service':node('ホットエンド交換の手順を確認する','交換対象が標準Nextruder用のホットエンドであることを確認します。ヒーター・サーミスターの配線を切り離す手順から、取付後のテストまで順に進めます。',{sources:['hotendAssembly'],tasks:['hotend'],choices:again}),
 'bed-temperature':node('ベッドのエラー番号と配線を確認する','冷却・抜栓後に、ベッドの配線の傷みや挟み込みを公式手順で確認します。過電流や温度異常が続く場合は再試行を繰り返さず、エラー番号と状態をサポートへ伝えます。CORE One LのACベッドはこの3Dの対象外です。',{sources:['bedTemp','overcurrent'],tasks:['electronics'],choices:again}),
 'chamber-temperature':node('昇温不足と過熱を分ける','昇温しない場合と熱くなり過ぎる場合では、換気の操作が逆になります。画面の番号を確認してください。',{sources:['chamberLow','chamberHigh'],choices:[choice('Failed to reach chamber temperature #31259','chamber-cold'),choice('危険温度・過熱 #31261など','chamber-hot'),choice('番号や状態が違う','support')]}),
 'chamber-cold':node('チャンバーの熱損失を確認する','公式記事で上部ベントと排気ファンの状態を確認します。PLAなどの印刷時に必要な換気とは区別し、材料と実機の指示に従います。温度が上がらないからと保護機能を変更しないでください。',{sources:['chamberLow'],choices:[choice('ファンのエラーもある','chamber-fan-check'),...again]}),
 'chamber-hot':node('印刷を止め、チャンバーを冷却する','危険温度のエラーでは印刷を止めます。排気と上部ベントによる冷却を公式手順で確認し、原因がわからないまま印刷を再開しないでください。',{sources:['chamberHigh'],choices:[choice('排気ファンの動作を確認したい','chamber-fan-check'),choice('冷却後も再発する','support'),choice('公式の確認を終えた','resolved')]}),
 electrical:node('配線の点検と基板交換を分ける','まず冷却・電源切断・抜栓を済ませます。端子のラッチと配線の両端を公式図で確認してください。接続不良か基板故障か不明な状態で、基板交換と決めつけないでください。',{sources:['selftest','care'],tasks:['electronics'],choices:[choice('LoveBoard交換を案内された','board-service'),choice('接続先がわからない・損傷がある','support'),choice('点検を終えた','resolved')]}),
 'board-service':node('指定された基板と交換手順を確認する','LoveBoard・xBuddy・xBuddy拡張基板は別の部品です。以下はLoveBoardの交換手順です。交換指示や部品が一致しない場合は、該当する公式ガイドを確認します。',{sources:['support'],tasks:['loveboard'],choices:again}),
 startup:node('どの段階で止まりますか？','失敗したテスト名や、画面が止まったときに機械も止まったかを確認します。',{sources:['selftest'],choices:[choice('セルフテストが失敗する','selftest-kind'),choice('初期設定の進め方を見たい','setup-guide'),choice('画面が応答しない','ui-stopped'),choice('ファームウェアの更新・書き直しを案内された','firmware-service'),choice('起動しない・再起動を繰り返す','support')]}),
 'firmware-service':node('更新する版と機種を確認する','ファームウェアの更新と、同じ版・古い版の書き直しでは起動時の操作が異なります。装着した機種に合うファイルと公式手順を選びます。詰まりや温度異常が直るとは限らないため、症状の点検も続けてください。',{sources:['firmwareUpdate','firmwareReflash'],choices:[choice('対象機種の新しい版へ更新する','firmware-update-guide'),choice('同じ版・古い版への書き直しを案内された','firmware-reflash-guide'),choice('適合する版がわからない','support')]}),
 'firmware-update-guide':node('新しい版への更新手順を確認する','公式ダウンロードで対象機種と版を確認し、更新手順へ進みます。実機への書き込みが終わってから、インストールされた版を実機で確認してください。',{sources:['firmwareUpdate'],tasks:['firmware-update'],choices:again}),
 'firmware-reflash-guide':node('指定された版への書き直しを確認する','同じ版・古い版を書き直す場合は、通常の更新と異なる公式手順を使います。対象機種・指定された版・ファイル名を確認し、不明なまま別機種のファイルを使わないでください。',{sources:['firmwareReflash'],tasks:['firmware-reflash'],choices:again}),
 'selftest-kind':node('失敗したテストを選ぶ','安定した台に設置し、失敗した項目を公式説明で確認します。原因を確認せずに全テストを繰り返さず、該当項目から確認を進めます。',{sources:['selftest'],choices:[choice('ファン','fan-kind'),choice('X・Y軸','xy-motion'),choice('Z軸・ベッド','z-motion'),choice('ロードセル','loadcell'),choice('フィラメントセンサー','sensor-kind'),choice('ヒーター・温度','error-kind'),choice('ドアなど、その他の項目','support')]}),
 'setup-guide':node('初期設定を順に確認する','実機の表示例と一緒に、初期設定・セルフテスト・フィラメント・最初の印刷を確認できます。各テスト中は画面の指示を優先します。',{sources:['selftest'],tasks:['initial-setup'],choices:[choice('失敗した項目がある','selftest-kind'),choice('確認を終えた','resolved')]}),
 'ui-stopped':node('停止した場面を控える','印刷開始時・終了時・メニュー操作中など、停止した場面と実機のファームウェアを控えます。画面だけか、動作も止まったかを分けてサポートへ伝えます。機種に合わないファームウェアを入れないでください。',{sources:['support'],choices:[choice('停止を繰り返す・状態が不明','support')]}),
 routine:node('手入れする部位を選ぶ','稼働時間と汚れに合わせて作業を選びます。潤滑剤と洗浄剤は部位ごとに確認してください。',{sources:['care'],choices:[choice('本体・パネル・シート','routine-clean'),choice('Yロッド・Xレール','lubrication'),choice('ファン・送りギア・ノズル外側','routine-head'),choice('電装の定期点検','electrical')]}),
 'routine-clean':node('本体とシートを手入れする','冷却後に本体の異物を取り除きます。パネルにはアルコールを使いません。シートは種類に合う方法で洗浄します。',{sources:['care','sheet'],tasks:['debris','panels','sheet'],choices:again}),
 lubrication:node('YロッドとXレールを区別する','Y軸の滑らかなロッドにはPrusa Lubricantを少量使います。X軸リニアレールにはGL 261を含む専用セットを使います。剤を混用せず、注油箇所は公式写真で確認します。',{sources:['care'],tasks:['rod','rail'],choices:again}),
 'routine-head':node('ファン・ギア・ノズル外側を手入れする','ファンの清掃、送りギアの粉の除去、ノズル外側の樹脂除去は作業条件が異なります。加熱が必要な作業は、選んだ手順の順序に従ってください。送りギアとアイドラーベアリングには注油しません。',{sources:['care'],tasks:['fans','extruder','hotend-clean'],choices:again}),
 'other-configuration':node('装備に合う公式ガイドを使う','この3Dは標準NextruderのCORE One / CORE One+を示しています。HT Hotend、V6アダプター、INDX、MMU、CORE One Lなどには、その装備の専用手順を使います。装備名を確認し、不明な場合はPrusaサポートへ相談してください。',{sources:['support'],choices:[choice('標準NextruderのCORE One / CORE One+だった','start'),choice('装備を確認したい','support')]}),
 resolved:node('作業後の動作を確認する','外した部品・配線・PTFE・カバーを戻し、選んだ公式手順の最後の確認を済ませます。必要なテスト、ロード・アンロード、パージや短い印刷で確認してください。時間が経ってから起きる症状は、同じ時間でも再発しないか確かめます。',{sources:['care','selftest'],choices:[choice('同じ症状が再発した','support'),choice('別の症状を確認したい','start')]})
 };
}
